import { Injectable } from '@angular/core';
import { VeniceImageModel } from 'supabase/functions/venice/models';

export interface StorageSchema {
  'selected-bible-id': string;
  'selected-public-bible-id': string;
  'preferred-model-provider': 'openai' | 'veniceai' | 'xai';
  'preferred-venice-model': VeniceImageModel;
}

export type StorageKey = keyof StorageSchema;

@Injectable({
  providedIn: 'root'
})
export class LocalStorageService {
  setItem<K extends StorageKey>(key: K, value: StorageSchema[K]): void {
    if (typeof value === 'string') {
      localStorage.setItem(key, value);
    } else {
      localStorage.setItem(key, JSON.stringify(value));
    }
  }

  getItem<K extends StorageKey>(key: K): StorageSchema[K] | null {
    const item = localStorage.getItem(key);
    if (!item) return null;
    
    try {
      return JSON.parse(item) as StorageSchema[K];
    } catch {
      return item as StorageSchema[K];
    }
  }

  removeItem(key: StorageKey): void {
    localStorage.removeItem(key);
  }

  clear(): void {
    localStorage.clear();
  }
}
